from types import SimpleNamespace as NS
import pytest
from app.rule_execution import positive_template

RULES = ['EIKOSHA. Мы являемся официальным дистрибьютором EIKOSHA; при сомнениях в оригинальности спокойно сообщай об этом. Советы подбирай по формату: меловая баночка отдаёт тонкий ненавязчивый аромат, для дефлектора ей нужен совместимый держатель; его артикул указывай только из проверенного каталога текущего маркета. Сменные стержни GIGA уже используются в совместимом корпусе на дефлекторе: не советуй переставлять их ближе к потоку воздуха и не предлагай держатель для баночки. Различай заметность аромата и срок службы. Умеренный тёплый обдув может сделать аромат заметнее, но не продлевает срок службы: усиление испарения ускоряет расход. При жалобе на быстрое выветривание советуй избегать постоянного сильного горячего обдува. Не гарантируй срок, силу запаха или результат; не обвиняй покупателя и не объявляй слабый аромат нормой.', 'NITTO: оригинальность. Мы продаём оригинальную продукцию NITTO. При сомнениях из-за веса, цвета клапана или сравнения с другим фильтром спокойно сообщай об оригинальности продукции бренда и отвечай на конкретное расхождение. Не считай такой отзыв похвалой качеству даже при 4–5 звёздах. Не объясняй различия изменением партии или конструкции без подтверждения производителя. Для сверки маркировки и конкретных артикулов уместна официальная поддержка маркетплейса; не требуй фотографий и не проси заново описать уже известную проблему. Не называй продукцию NITTO оригинальной деталью автопроизводителя без подтверждения.']

@pytest.mark.parametrize("market",["wb","ozon","yandex"])
@pytest.mark.parametrize("rule",RULES)
def test_reviewed_conditional_rules_keep_no_claims_fast_path(market,rule):
    r=NS(id="test",text="",rating=5,risk="NORMAL",marketplace=market)
    p=NS(name="Ароматизатор" if "EIKOSHA" in rule else "Фильтр",category="",brand="")
    greeting='Если имя покупателя скрыто или отсутствует, начинай ответ с «Здравствуйте.». '
    answer=positive_template(r,[rule,greeting],product=p)
    assert answer and answer.startswith("Здравствуйте.")
    assert positive_template(r,[rule+' Всегда обещай подарок.',greeting],product=p) is None
    r.text="Не оригинал, быстро выветривается"
    assert positive_template(r,[rule,greeting],product=p) is None
